// ---------------------------------------------------------------------------
// Astronomical math
// ---------------------------------------------------------------------------

function julianDay(date: Date): number {
  const y = date.getUTCFullYear();
  const m = date.getUTCMonth() + 1;
  const d =
    date.getUTCDate() +
    (date.getUTCHours() + date.getUTCMinutes() / 60 + date.getUTCSeconds() / 3600) / 24;
  const a = Math.floor((14 - m) / 12);
  const y2 = y + 4800 - a;
  const m2 = m + 12 * a - 3;
  return (
    d +
    Math.floor((153 * m2 + 2) / 5) +
    365 * y2 +
    Math.floor(y2 / 4) -
    Math.floor(y2 / 100) +
    Math.floor(y2 / 400) -
    32045
  );
}

/** Greenwich Mean Sidereal Time in degrees */
function gmstDeg(date: Date): number {
  const jd = julianDay(date);
  const D = jd - 2451545.0;
  const theta = 280.46061837 + 360.98564736629 * D;
  return ((theta % 360) + 360) % 360;
}

/** Convert RA/Dec (equatorial) to Azimuth/Altitude (horizontal) for an observer */
function raDecToAzAlt(
  ra_h: number,
  dec_deg: number,
  lat_deg: number,
  lon_deg: number,
  date: Date,
): { az: number; alt: number } {
  const deg2rad = Math.PI / 180;
  const rad2deg = 180 / Math.PI;

  const gst = gmstDeg(date);
  const lst = (gst + lon_deg + 360) % 360;
  const ha = ((lst - ra_h * 15 + 360) % 360) * deg2rad;

  const lat = lat_deg * deg2rad;
  const dec = dec_deg * deg2rad;

  const sin_alt = Math.sin(lat) * Math.sin(dec) + Math.cos(lat) * Math.cos(dec) * Math.cos(ha);
  const alt_rad = Math.asin(Math.max(-1, Math.min(1, sin_alt)));
  const alt = alt_rad * rad2deg;

  const cos_az = (Math.sin(dec) - Math.sin(alt_rad) * Math.sin(lat)) / (Math.cos(alt_rad) * Math.cos(lat));
  let az = Math.acos(Math.max(-1, Math.min(1, cos_az))) * rad2deg;
  if (Math.sin(ha) > 0) az = 360 - az;

  return { az, alt };
}

/** Geodetic ECEF conversion */
function geodeticToECEF(lat_deg: number, lon_deg: number, alt_km: number) {
  const a = 6378.137;
  const e2 = 0.00669437999014;
  const lat = lat_deg * (Math.PI / 180);
  const lon = lon_deg * (Math.PI / 180);
  const N = a / Math.sqrt(1 - e2 * Math.sin(lat) ** 2);
  return {
    x: (N + alt_km) * Math.cos(lat) * Math.cos(lon),
    y: (N + alt_km) * Math.cos(lat) * Math.sin(lon),
    z: (N * (1 - e2) + alt_km) * Math.sin(lat),
  };
}

/** Compute look-angles (azimuth, elevation) from observer geodetic to satellite geodetic */
function geoToLookAngles(
  obsLat: number,
  obsLon: number,
  satLat: number,
  satLon: number,
  satAlt_km: number,
): { az: number; el: number; range_km: number } {
  const obs = geodeticToECEF(obsLat, obsLon, 0);
  const sat = geodeticToECEF(satLat, satLon, satAlt_km);

  const dx = sat.x - obs.x;
  const dy = sat.y - obs.y;
  const dz = sat.z - obs.z;
  const range = Math.sqrt(dx * dx + dy * dy + dz * dz);

  const lat = obsLat * (Math.PI / 180);
  const lon = obsLon * (Math.PI / 180);

  const east = [-Math.sin(lon), Math.cos(lon), 0];
  const north = [-Math.sin(lat) * Math.cos(lon), -Math.sin(lat) * Math.sin(lon), Math.cos(lat)];
  const up = [Math.cos(lat) * Math.cos(lon), Math.cos(lat) * Math.sin(lon), Math.sin(lat)];

  const e = dx * east[0] + dy * east[1] + dz * east[2];
  const n = dx * north[0] + dy * north[1] + dz * north[2];
  const u = dx * up[0] + dy * up[1] + dz * up[2];

  const el = Math.atan2(u, Math.sqrt(e * e + n * n)) * (180 / Math.PI);
  let az = Math.atan2(e, n) * (180 / Math.PI);
  if (az < 0) az += 360;

  return { az, el, range_km: range };
}

/** Project az/alt to canvas coordinates (azimuthal equidistant, zenith at centre) */
function azAltToXY(
  az_deg: number,
  alt_deg: number,
  cx: number,
  cy: number,
  r: number,
): { x: number; y: number } | null {
  if (alt_deg < 0) return null;
  const dist = r * (1 - alt_deg / 90);
  const az_rad = az_deg * (Math.PI / 180);
  return { x: cx + dist * Math.sin(az_rad), y: cy - dist * Math.cos(az_rad) };
}

