// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function NightSky() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [canvasSize, setCanvasSize] = useState(480);
  const [tick, setTick] = useState(0);
  const [now, setNow] = useState(new Date());

  const { data: issData } = useISSPosition(5000);
  const { location: geoLocation, status: geoStatus } = useGeolocation();

  const [obsLat, setObsLat] = useState(48.85);
  const [obsLon, setObsLon] = useState(2.35);
  const [latInput, setLatInput] = useState('48.85');
  const [lonInput, setLonInput] = useState('2.35');

  // Use geolocation when available
  useEffect(() => {
    if (geoLocation) {
      setObsLat(geoLocation.lat);
      setObsLon(geoLocation.lon);
      setLatInput(geoLocation.lat.toFixed(3));
      setLonInput(geoLocation.lon.toFixed(3));
    }
  }, [geoLocation]);

  // Canvas resize observer
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ro = new ResizeObserver((entries) => {
      const w = entries[0].contentRect.width;
      setCanvasSize(Math.max(280, Math.min(w, 540)));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // Tick every 10s to re-draw (sky moves slowly)
  useEffect(() => {
    const id = setInterval(() => {
      setTick((t) => t + 1);
      setNow(new Date());
    }, 10000);
    return () => clearInterval(id);
  }, []);

  // Draw star chart
  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const date = new Date();
    const size = canvasSize;
    const cx = size / 2;
    const cy = size / 2;
    const r = size / 2 - 18;

    ctx.clearRect(0, 0, size, size);

    // Background gradient
    const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
    grad.addColorStop(0, '#06060f');
    grad.addColorStop(0.7, '#08091a');
    grad.addColorStop(1, '#0b0c1e');
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, size, size);
    ctx.restore();

    // Elevation grid circles (30° and 60°)
    for (const alt of [30, 60]) {
      const dist = r * (1 - alt / 90);
      ctx.beginPath();
      ctx.arc(cx, cy, dist, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(255,255,255,0.04)';
      ctx.lineWidth = 0.8;
      ctx.stroke();
    }

    // Horizon circle
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.12)';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Constellation lines
    CONSTELLATIONS.forEach((constellation) => {
      ctx.strokeStyle = constellation.color + '50';
      ctx.lineWidth = 0.9;
      constellation.lines.forEach(([id1, id2]) => {
        const s1 = STAR_BY_ID[id1];
        const s2 = STAR_BY_ID[id2];
        if (!s1 || !s2) return;

        const p1 = raDecToAzAlt(s1.ra, s1.dec, obsLat, obsLon, date);
        const p2 = raDecToAzAlt(s2.ra, s2.dec, obsLat, obsLon, date);
        if (p1.alt < 0 || p2.alt < 0) return;

        const xy1 = azAltToXY(p1.az, p1.alt, cx, cy, r);
        const xy2 = azAltToXY(p2.az, p2.alt, cx, cy, r);
        if (!xy1 || !xy2) return;

        ctx.beginPath();
        ctx.moveTo(xy1.x, xy1.y);
        ctx.lineTo(xy2.x, xy2.y);
        ctx.stroke();
      });
    });

    // Stars
    STARS.forEach((star) => {
      const pos = raDecToAzAlt(star.ra, star.dec, obsLat, obsLon, date);
      if (pos.alt < 0) return;

      const xy = azAltToXY(pos.az, pos.alt, cx, cy, r);
      if (!xy) return;

      const starR = Math.max(0.4, 2.8 - star.mag * 0.55);
      const brightness = Math.min(1, Math.max(0.25, 1 - (star.mag - -1.5) * 0.12));

      // Glow for bright stars
      if (star.mag < 1.5) {
        const glow = ctx.createRadialGradient(xy.x, xy.y, 0, xy.x, xy.y, starR * 3);
        glow.addColorStop(0, `rgba(255,255,220,${brightness * 0.5})`);
        glow.addColorStop(1, 'rgba(255,255,220,0)');
        ctx.beginPath();
        ctx.arc(xy.x, xy.y, starR * 3, 0, Math.PI * 2);
        ctx.fillStyle = glow;
        ctx.fill();
      }

      ctx.beginPath();
      ctx.arc(xy.x, xy.y, starR, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(255,255,220,${brightness})`;
      ctx.fill();
    });

    // ISS overlay
    if (issData) {
      const look = geoToLookAngles(obsLat, obsLon, issData.latitude, issData.longitude, issData.altitude);
      if (look.el > 0) {
        const xy = azAltToXY(look.az, look.el, cx, cy, r);
        if (xy) {
          // Outer glow
          const issGlow = ctx.createRadialGradient(xy.x, xy.y, 0, xy.x, xy.y, 12);
          issGlow.addColorStop(0, 'rgba(255,215,0,0.4)');
          issGlow.addColorStop(1, 'rgba(255,215,0,0)');
          ctx.beginPath();
          ctx.arc(xy.x, xy.y, 12, 0, Math.PI * 2);
          ctx.fillStyle = issGlow;
          ctx.fill();

          // ISS dot
          ctx.beginPath();
          ctx.arc(xy.x, xy.y, 5, 0, Math.PI * 2);
          ctx.fillStyle = '#ffd700';
          ctx.fill();
          ctx.strokeStyle = '#fffacd';
          ctx.lineWidth = 1;
          ctx.stroke();

          // Label
          ctx.font = `bold 11px ${theme.typography.fontFamilyMono}`;
          ctx.fillStyle = '#ffd700';
          ctx.fillText('ISS', xy.x + 8, xy.y + 4);

          // Elevation label
          ctx.font = `10px ${theme.typography.fontFamilyMono}`;
          ctx.fillStyle = '#ffd70099';
          ctx.fillText(`${look.el.toFixed(1)}° el`, xy.x + 8, xy.y + 16);
        }
      }
    }

    // Cardinal direction labels
    ctx.font = `bold 11px sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const cardinals = [
      { az: 0, label: 'N' },
      { az: 90, label: 'E' },
      { az: 180, label: 'S' },
      { az: 270, label: 'W' },
    ];
    cardinals.forEach(({ az, label }) => {
      const az_rad = az * (Math.PI / 180);
      const x = cx + (r + 12) * Math.sin(az_rad);
      const y = cy - (r + 12) * Math.cos(az_rad);
      ctx.fillStyle = label === 'N' ? '#58a6ff' : '#8b949e';
      ctx.fillText(label, x, y);
    });

    // Zenith label
    ctx.font = `9px sans-serif`;
    ctx.fillStyle = 'rgba(255,255,255,0.15)';
    ctx.textAlign = 'center';
    ctx.fillText('Zenith', cx, cy + 4);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
  }, [obsLat, obsLon, issData, canvasSize]);

  // Re-draw whenever dependencies change
  useEffect(() => {
    draw();
  }, [draw, tick]);

  // ISS look angles for sidebar
  const issLook = issData
    ? geoToLookAngles(obsLat, obsLon, issData.latitude, issData.longitude, issData.altitude)
    : null;

  const issVisible = issLook && issLook.el > 0;

  return (
    <Wrapper>
      <Header>
        <Title>
          <Star size={18} color="#ffd700" />
          Night Sky
        </Title>
        <Controls>
          <LocationInfo>
            <MapPin size={12} />
            <Label>Lat</Label>
            <Input
              type="number"
              value={latInput}
              onChange={(e) => {
                setLatInput(e.target.value);
                const v = parseFloat(e.target.value);
                if (!isNaN(v) && v >= -90 && v <= 90) setObsLat(v);
              }}
              step="0.001"
              min="-90"
              max="90"
            />
            <Label>Lon</Label>
            <Input
              type="number"
              value={lonInput}
              onChange={(e) => {
                setLonInput(e.target.value);
                const v = parseFloat(e.target.value);
                if (!isNaN(v) && v >= -180 && v <= 180) setObsLon(v);
              }}
              step="0.001"
              min="-180"
              max="180"
            />
          </LocationInfo>
          {geoStatus === 'granted' && (
            <LocationInfo style={{ color: '#3fb950' }}>
              <MapPin size={11} />
              GPS
            </LocationInfo>
          )}
          <RefreshBtn
            onClick={() => {
              setTick((t) => t + 1);
              setNow(new Date());
            }}
          >
            <RefreshCw size={11} />
            Refresh
          </RefreshBtn>
        </Controls>
      </Header>

      <Body>
        <CanvasWrap ref={containerRef}>
          <StyledCanvas
            ref={canvasRef}
            width={canvasSize}
            height={canvasSize}
          />
        </CanvasWrap>

        <Sidebar>
          <SidebarSection>
            <SidebarTitle>ISS Visibility</SidebarTitle>
            {issData && issLook ? (
              issVisible ? (
                <ISSInfo>
                  <ISSRow>
                    <ISSKey>Elevation</ISSKey>
                    <span>{issLook.el.toFixed(1)}°</span>
                  </ISSRow>
                  <ISSRow>
                    <ISSKey>Azimuth</ISSKey>
                    <span>{issLook.az.toFixed(1)}°</span>
                  </ISSRow>
                  <ISSRow>
                    <ISSKey>Range</ISSKey>
                    <span>{issLook.range_km.toFixed(0)} km</span>
                  </ISSRow>
                  <ISSRow>
                    <ISSKey>Sun</ISSKey>
                    <span>{issData.visibility}</span>
                  </ISSRow>
                </ISSInfo>
              ) : (
                <NotVisible>
                  ISS is currently below the horizon.
                  <br />
                  El: {issLook.el.toFixed(1)}°
                </NotVisible>
              )
            ) : (
              <NotVisible>Loading ISS data…</NotVisible>
            )}
          </SidebarSection>

          <SidebarSection>
            <SidebarTitle>Constellations</SidebarTitle>
            {CONSTELLATIONS.map((c) => (
              <ConstellationItem key={c.name}>
                <ConstellationLine color={c.color} />
                {c.name}
              </ConstellationItem>
            ))}
          </SidebarSection>

          <SidebarSection>
            <SidebarTitle>How to read</SidebarTitle>
            <NotVisible>
              Centre = zenith (directly overhead).
              Edge = horizon.
              N is up. Stars are sized by brightness.
              ISS shown in gold when visible.
            </NotVisible>
          </SidebarSection>
        </Sidebar>
      </Body>

      <TimeDisplay>
        UTC {now.toUTCString().split(' ')[4]} · Observer {obsLat.toFixed(3)}° {obsLat >= 0 ? 'N' : 'S'},{' '}
        {Math.abs(obsLon).toFixed(3)}° {obsLon >= 0 ? 'E' : 'W'}
      </TimeDisplay>
    </Wrapper>
  );
}
