export interface SatPosition {
  norad: number;
  name: string;
  category: SatCategory;
  latitude: number;
  longitude: number;
  altitude: number;
}

// TLE cache — fetched once per hour
interface CachedTLE {
  line1: string;
  line2: string;
  fetchedAt: number;
}
const TLE_CACHE = new Map<number, CachedTLE>();
const TLE_TTL = 60 * 60 * 1000; // 1 hour

async function fetchTLE(norad: number): Promise<{ line1: string; line2: string } | null> {
  const cached = TLE_CACHE.get(norad);
  if (cached && Date.now() - cached.fetchedAt < TLE_TTL) {
    return { line1: cached.line1, line2: cached.line2 };
  }
  try {
    const res = await fetch(`https://tle.ivanstanojevic.me/api/tle/${norad}`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const json = await res.json();
    if (!json.line1 || !json.line2) throw new Error('No TLE lines');
    TLE_CACHE.set(norad, { line1: json.line1, line2: json.line2, fetchedAt: Date.now() });
    return { line1: json.line1, line2: json.line2 };
  } catch {
    return null;
  }
}

function propagateTLE(
  line1: string,
  line2: string,
  date: Date,
): { latitude: number; longitude: number; altitude: number } | null {
  try {
    const satrec = twoline2satrec(line1, line2);
    const pv = propagate(satrec, date);
    if (!pv.position || typeof pv.position === 'boolean') return null;
    const gst = gstime(date);
    const geo = eciToGeodetic(pv.position as { x: number; y: number; z: number }, gst);
    return {
      latitude:  degreesLat(geo.latitude),
      longitude: degreesLong(geo.longitude),
      altitude:  geo.height,
    };
  } catch {
    return null;
  }
}

export function useSatellites(tickMs = 5000) {
  const [sats, setSats] = useState<SatPosition[]>([]);

  // Fetch all TLEs once on mount (and refresh every hour via cache TTL)
  const loadTLEs = useCallback(async () => {
    const results = await Promise.allSettled(
      SAT_CATALOG.map(async (entry, i) => {
        await new Promise((r) => setTimeout(r, i * 120)); // gentle stagger
        return fetchTLE(entry.norad);
      }),
    );
    // Immediately compute positions after loading
    const now = new Date();
    const positions: SatPosition[] = [];
    results.forEach((r, i) => {
      if (r.status !== 'fulfilled' || !r.value) return;
      const entry = SAT_CATALOG[i];
      const pos = propagateTLE(r.value.line1, r.value.line2, now);
      if (pos) positions.push({ norad: entry.norad, name: entry.name, category: entry.category, ...pos });
    });
    if (positions.length > 0) setSats(positions);
  }, []);

  useEffect(() => {
    loadTLEs();
    // Re-fetch TLEs every hour
    const fetchId = setInterval(loadTLEs, TLE_TTL);
    return () => clearInterval(fetchId);
  }, [loadTLEs]);

  // Propagate positions every tickMs using cached TLEs (no network)
  useEffect(() => {
    const id = setInterval(() => {
      const now = new Date();
      const positions: SatPosition[] = [];
      SAT_CATALOG.forEach((entry) => {
        const cached = TLE_CACHE.get(entry.norad);
        if (!cached) return;
        const pos = propagateTLE(cached.line1, cached.line2, now);
        if (pos) positions.push({ norad: entry.norad, name: entry.name, category: entry.category, ...pos });
      });
      if (positions.length > 0) setSats(positions);
    }, tickMs);
    return () => clearInterval(id);
  }, [tickMs]);

  return sats;
}

export function useOrbitTrail(maxPoints = 60) {
  const trailRef = useRef<Array<[number, number]>>([]);
  const [trail, setTrail] = useState<Array<[number, number]>>([]);

  const addPoint = useCallback((lat: number, lng: number) => {
    trailRef.current = [...trailRef.current, [lat, lng]].slice(-maxPoints);
    setTrail([...trailRef.current]);
  }, [maxPoints]);

  return { trail, addPoint };
}
